import React from 'react';
import {Composition, registerRoot, useCurrentFrame} from 'remotion';
const Sample = () => <div style={{background: '#197f86', width: '100%', height: '100%'}}>{useCurrentFrame()}</div>;
registerRoot(() => <Composition id="Sample" component={Sample} durationInFrames={60} fps={30} width={160} height={90}/>);
